mapper.update:
UPDATE animal
SET animal_name = #{animalName}, type = #{type}, color = #{color}, location = #{location}, status = #{status}, photo_url = #{photoUrl}, remark = #{remark}, is_approved = #{isApproved}
WHERE animal_id = #{animalId}

mapper.select:
SELECT  FROM animal 
ORDER BY create_time DESC, animal_id DESC
LIMIT #{limit} OFFSET #{offset}
